<template>
  <div class="workspace-page teacher-students-page">
    <section class="workspace-hero"><div><p class="workspace-kicker">{{ t('teacherStudents.kicker') }}</p><h1>{{ t('teacherStudents.title') }}</h1><p>{{ t('teacherStudents.description') }}</p></div><div class="workspace-identity"><span class="material-symbols-outlined" aria-hidden="true">school</span><div><strong>{{ auth.user?.display_name || auth.user?.username }}</strong><span>{{ t('role.teacher') }}</span></div></div></section>
    <div v-if="error" class="error-banner" role="alert">{{ error }}</div><div v-if="notice" class="ok-banner" role="status">{{ notice }}</div>
    <div class="workspace-layout"><main class="workspace-main"><section class="panel"><div class="panel-heading"><div><p class="workspace-kicker">{{ t('teacherStudents.listKicker') }}</p><h2>{{ t('teacherStudents.list') }}</h2><p>{{ t('teacherStudents.listDetail') }}</p></div><button class="icon-button" type="button" :title="t('teacherStudents.refresh')" :aria-label="t('teacherStudents.refresh')" :disabled="loading" @click="load"><span class="material-symbols-outlined">refresh</span></button></div><AsyncState v-if="loading" state="loading" :title="t('teacherStudents.loading')" /><AsyncState v-else-if="!students.length" state="empty" :title="t('teacherStudents.empty')" :detail="t('teacherStudents.emptyDetail')" /><div v-else class="table-scroll"><table class="student-table"><thead><tr><th>{{ t('teacherStudents.account') }}</th><th>{{ t('teacherStudents.name') }}</th><th>{{ t('teacherStudents.thesis') }}</th><th>{{ t('teacherStudents.words') }}</th><th>{{ t('teacherStudents.lastSaved') }}</th><th>{{ t('teacherStudents.actions') }}</th></tr></thead><tbody><tr v-for="student in students" :key="student.id"><td><strong>{{ student.username }}</strong></td><td>{{ student.display_name }}</td><td>{{ student.latest_project_title || t('teacherStudents.noThesis') }}</td><td>{{ student.total_words || 0 }}</td><td>{{ formatDate(student.last_updated) }}</td><td class="student-actions"><button class="tiny" type="button" @click="resetPassword(student)">{{ t('teacherStudents.resetPassword') }}</button><button class="tiny danger" type="button" @click="unbind(student)">{{ t('teacherStudents.unbind') }}</button></td></tr></tbody></table></div></section></main><aside class="workspace-side"><section class="panel"><div class="panel-heading"><div><p class="workspace-kicker">{{ t('teacherStudents.importKicker') }}</p><h2>{{ t('teacherStudents.import') }}</h2><p>{{ t('teacherStudents.importDetail') }}</p></div><span class="material-symbols-outlined panel-icon">group_add</span></div><form class="student-import-form" @submit.prevent="importStudents"><textarea v-model="rawText" rows="7" :placeholder="t('teacherStudents.importPlaceholder')" required /><label>{{ t('teacherStudents.initialPassword') }}<input v-model="defaultPassword" type="password" minlength="8" autocomplete="new-password" /></label><label class="checkbox-row"><input v-model="forceChange" type="checkbox" />{{ t('teacherStudents.forceChange') }}</label><button class="small primary" type="submit" :disabled="importing"><span class="material-symbols-outlined">publish</span>{{ importing ? t('teacherStudents.importing') : t('teacherStudents.importButton') }}</button></form><div v-if="importResult" class="import-result"><p>{{ t('teacherStudents.importResult', { success: importResult.success_count || 0, failed: importResult.failed?.length || 0 }) }}</p><div v-for="item in importResult.created || []" :key="item.username" class="import-created"><strong>{{ item.username }}</strong><span>{{ item.display_name }} · {{ item.initial_password || t('teacherStudents.existingAccount') }}</span></div><div v-for="item in importResult.failed || []" :key="item.username" class="preview-error">{{ item.username }}：{{ item.reason }}</div></div></section></aside></div>
    <ConfirmDialog :open="confirmDialog.open" :title="confirmDialog.title" :description="confirmDialog.description" :confirm-label="confirmDialog.confirmLabel" :danger="true" :busy="confirmBusy" @confirm="confirmAction" @cancel="closeConfirm" />
  </div>
</template>

<script setup>
import { onMounted, ref } from 'vue'
import { auth } from '../auth'
import { bulkImportStudents, getTeacherStudents, resetTeacherStudentPassword, unbindTeacherStudent } from '../api'
import AsyncState from '../components/AsyncState.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import { useI18n } from '../i18n'

const { t, formatDate: formatLocaleDate } = useI18n()
const students = ref([]); const loading = ref(true); const importing = ref(false); const error = ref(''); const notice = ref(''); const rawText = ref(''); const defaultPassword = ref('Student123456'); const forceChange = ref(true); const importResult = ref(null); const confirmBusy = ref(false); const confirmDialog = ref({ open: false, title: '', description: '', confirmLabel: '', action: null })
async function load() { loading.value = true; error.value = ''; try { const result = await getTeacherStudents(); students.value = result.students || [] } catch (exception) { error.value = exception.message } finally { loading.value = false } }
function parseStudents() { return rawText.value.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).map((line) => { const parts = line.split(/[\t,，\s]+/); return { username: parts[0] || '', display_name: parts.slice(1).join(' ') || parts[0] || '' } }).filter((item) => item.username && item.display_name) }
async function importStudents() { const parsed = parseStudents(); if (!parsed.length) { error.value = t('teacherStudents.invalidInput'); return }; importing.value = true; error.value = ''; try { importResult.value = await bulkImportStudents({ students: parsed, default_password: defaultPassword.value || 'Student123456', force_change_password: forceChange.value }); notice.value = t('teacherStudents.imported', { count: importResult.value.success_count || 0 }); rawText.value = ''; await load() } catch (exception) { error.value = exception.message } finally { importing.value = false } }
function resetPassword(student) { Object.assign(confirmDialog.value, { open: true, title: t('teacherStudents.resetTitle'), description: t('teacherStudents.resetDescription', { name: student.display_name, username: student.username }), confirmLabel: t('teacherStudents.resetConfirm'), action: async () => { await resetTeacherStudentPassword(student.id, { new_password: 'Student123456', force_change_password: true }); notice.value = t('teacherStudents.resetDone', { name: student.display_name }) } }) }
function unbind(student) { Object.assign(confirmDialog.value, { open: true, title: t('teacherStudents.unbindTitle'), description: t('teacherStudents.unbindDescription', { name: student.display_name, username: student.username }), confirmLabel: t('teacherStudents.unbindConfirm'), action: async () => { await unbindTeacherStudent(student.id); notice.value = t('teacherStudents.unbound', { name: student.display_name }); await load() } }) }
async function confirmAction() { const action = confirmDialog.value.action; if (!action) return; confirmBusy.value = true; try { await action() } catch (exception) { error.value = exception.message } finally { confirmBusy.value = false; closeConfirm() } }
function closeConfirm() { if (confirmBusy.value) return; confirmDialog.value.open = false; confirmDialog.value.action = null }
function formatDate(value) { return value ? formatLocaleDate(value, { hour12: false }) : '-' }
onMounted(load)
</script>

<style scoped>
.table-scroll { overflow-x: auto; margin-top: 14px; }.student-table { width: 100%; min-width: 760px; border-collapse: collapse; font-size: 12px; }.student-table th, .student-table td { padding: 10px 8px; border-bottom: 1px solid var(--border); text-align: left; vertical-align: top; }.student-table th { color: var(--on-surface-variant); font-size: 11px; }.student-actions { display: flex; gap: 6px; }.student-import-form { display: grid; gap: 10px; margin-top: 14px; }.student-import-form textarea { width: 100%; resize: vertical; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; }.student-import-form label { display: grid; gap: 5px; color: var(--on-surface-variant); font-size: 12px; }.checkbox-row { display: flex !important; align-items: center; gap: 7px; }.checkbox-row input { accent-color: var(--primary); }.import-result { border-top: 1px solid var(--border); margin-top: 14px; padding-top: 10px; color: var(--on-surface-variant); font-size: 12px; }.import-result p { margin: 0 0 8px; }.import-created { display: grid; padding: 6px 0; border-bottom: 1px solid var(--border); }.import-created span { font-size: 11px; margin-top: 2px; }.preview-error { color: var(--error); }
</style>
